const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = data[0];
const coordsX = new Int32Array(N);
const coordsY = new Int32Array(N);

let pos = 1;
for (let i = 0; i < N; i++) {
  coordsX[i] = data[pos++];
  coordsY[i] = data[pos++];
}

const pairCount = N * N;
const eventCount = pairCount;
const weights = new Uint32Array(pairCount + N);
const dp = new Uint32Array(pairCount + N);
let ids = new Uint32Array(eventCount);
let temp = new Uint32Array(eventCount);

let index = 0;
for (let i = 0; i < N; i++) {
  for (let j = 0; j < N; j++) {
    if (i === j) continue;
    const dx = coordsX[i] - coordsX[j];
    const dy = coordsY[i] - coordsY[j];
    const id = i * N + j;
    weights[id] = dx * dx + dy * dy;
    ids[index++] = id;
  }
}

for (let i = 0; i < N; i++) {
  const id = pairCount + i;
  weights[id] = coordsX[i] * coordsX[i] + coordsY[i] * coordsY[i];
  ids[index++] = id;
}

for (let shift = 0; shift < 30; shift += 10) {
  const counts = new Uint32Array(1024);

  for (let i = 0; i < eventCount; i++) {
    counts[(weights[ids[i]] >>> shift) & 1023]++;
  }

  let sum = 0;
  for (let i = 0; i < 1024; i++) {
    const count = counts[i];
    counts[i] = sum;
    sum += count;
  }

  for (let i = 0; i < eventCount; i++) {
    const id = ids[i];
    const digit = (weights[id] >>> shift) & 1023;
    temp[counts[digit]++] = id;
  }

  const swap = ids;
  ids = temp;
  temp = swap;
}

const bestAt = new Uint32Array(N);
let answer = 1;
let end = eventCount;

while (end > 0) {
  const weight = weights[ids[end - 1]];
  let start = end - 1;
  while (start > 0 && weights[ids[start - 1]] === weight) start--;

  for (let k = start; k < end; k++) {
    const id = ids[k];
    if (id >= pairCount) {
      dp[id] = 1;
    } else {
      const from = Math.floor(id / N);
      dp[id] = bestAt[from] === 0 ? 0 : bestAt[from] + 1;
    }
  }

  for (let k = start; k < end; k++) {
    const id = ids[k];
    const value = dp[id];
    const target = id >= pairCount ? id - pairCount : id % N;

    if (value > bestAt[target]) bestAt[target] = value;
    if (value > answer) answer = value;
  }

  end = start;
}

console.log(answer.toString());
